# Let me try creating a horizontally symmetric output
grid = [
    [1, 1, 3, 1, 1, 1, 5, 1, 1, 1, 1, 1, 1],
    [3, 3, 1, 3, 1, 1, 5, 1, 1, 1, 1, 1, 1],
    [1, 3, 1, 1, 3, 3, 5, 1, 1, 1, 1, 1, 1],
    [1, 3, 4, 1, 3, 1, 5, 1, 1, 1, 1, 1, 1]
]

height, width = len(grid), len(grid[0])

# Create horizontally symmetric version
# For each position, take the most common value between j and mirror position
output = [[0]*width for _ in range(height)]
for i in range(height):
    for j in range(width):
        mirror_j = width - 1 - j
        if j == mirror_j:
            # Center point, keep original
            output[i][j] = grid[i][j]
        else:
            # Take max (or could use min, or count)
            val1 = grid[i][j]
            val2 = grid[i][mirror_j]
            # Count occurrences in the row
            if val1 == val2:
                output[i][j] = val1
            elif val1.count := sum(1 for x in grid[i] if x == val1) > val2.count := sum(1 for x in grid[i] if x == val2):
                output[i][j] = val1
            elif val2.count := sum(1 for x in grid[i] if x == val2) > val1.count := sum(1 for x in grid[i] if x == val1):
                output[i][j] = val2
            else:
                output[i][j] = val2  # Default to right side

print("Symmetric output:")
for row in output:
    print(row)

